nav=''.join(f'<button class="navitem" data-index="{i}" onclick="selectMail({i})"><span>{x["id"]} · J{x["jour"]} · {x["cta"]}</span>{e(x["objet"])}</button>' for i,x in enumerate(M))
opts=''.join(f'<option value="{i}">{x["id"]} · {e(x["objet"])}</option>' for i,x in enumerate(M))
